/// <summary>
/// Set range
/// </summary>
public void init()
{
    QueryBuildDataSource    definitionGroupExecutionDS;

    super();

    definitionGroupExecutionDS = this.query().dataSourceTable(tableNum(DMFDefinitionGroupExecution));

    definitionGroupExecutionDS.addRange(fieldNum(DMFDefinitionGroupExecution, RecId)).value(strFmt('((%1.%2 == 3) || ((%1.%2 == 4) && (%1.%3 != %1.%4) && (%1.%3 != %1.%5)))',
                                                                                                    definitionGroupExecutionDS.name(),
                                                                                                    fieldStr(DMFDefinitionGroupExecution, TargetStatus),
                                                                                                    fieldStr(DMFDefinitionGroupExecution, NoOfRecords),
                                                                                                    fieldStr(DMFDefinitionGroupExecution, NumOfTargetNew),
                                                                                                    fieldStr(DMFDefinitionGroupExecution, NumOfStagingNew)));
}
